import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  ViewEncapsulation,
} from '@angular/core';

import { SatAvatarActiveIndicator } from './indicators/active-indicator';
import { SatAvatarAwayIndicator } from './indicators/away-indicator';
import { SatAvatarOfflineIndicator } from './indicators/offline-indicator';
import { SatAvatarReadonlyIndicator } from './indicators/readonly-indicator';

/** The category of the avatar, which determines its color. */
export type SatAvatarCategory =
  | 'purple'
  | 'blue'
  | 'pink'
  | 'teal'
  | 'yellow'
  | 'green'
  | 'red'
  | 'orange';

/** The indicator type of the avatar, which determines its status. */
export type SatAvatarIndicator = 'active' | 'away' | 'offline' | 'readonly';

/** The size of the avatar, which determines its pixel size. */
export type SatAvatarSize = '128' | '80' | '64' | '36' | '28' | '24';

/**
 * The `sat-avatar` component is used to display user initials with various styles and indicators.
 * It supports different categories, sizes, and status indicators.
 */
@Component({
  selector: 'sat-avatar',
  templateUrl: './avatar.html',
  styleUrl: './avatar.scss',
  imports: [
    SatAvatarActiveIndicator,
    SatAvatarAwayIndicator,
    SatAvatarOfflineIndicator,
    SatAvatarReadonlyIndicator,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: { role: 'img' },
})
export class SatAvatar {
  /**
   * One out of: purple, blue, pink, teal, yellow, green, red, orange.
   * Used to determine the color of the avatar.
   */
  readonly category = input<SatAvatarCategory>('purple');
  /**
   * One out of: 24, 28, 36, 64, 80, 128.
   * Used as the pixel size of the avatar.
   */
  readonly size = input<SatAvatarSize>('24');
  /**
   * One out of: active, away, offline, readonly.
   * Used to determine the optional indicator displayed on the avatar.
   * If left unset, no indicator will be displayed.
   */
  readonly indicator = input<SatAvatarIndicator>();
  /**
   * The first two character of this string, or the first character of this string in size 24
   * will be displayed uppercase in the avatar.
   */
  readonly initials = input<string>('WW');
  /** Whether to not display a border around the avatar. Defaults to false. */
  readonly borderless = input<boolean>(false);

  /** @internal */
  readonly _displayedInitials = computed(() =>
    this.size() === '24'
      ? this.initials()[0].toUpperCase()
      : this.initials().slice(0, 2).toUpperCase(),
  );

  /** @internal */
  readonly _backgroundColor = computed(() => `var(--sat-avatar-cat-${this.category()}-container)`);
  /** @internal */
  readonly _color = computed(() => `var(--sat-avatar-on-cat-${this.category()}-container)`);
}
